  tot_morti        smallint NOT NULL DEFAULT 0,
  tot_feriti       smallint NOT NULL DEFAULT 0,
  gravita          text NOT NULL
);


CREATE INDEX accidents_geom_gist ON data.accidents USING GIST (geom);
